function seventy(){return 70;}

function quantity(q){if(!q)return 'Not reported';const v=/^\d+(?:\.\d+)?(?:\(\d+\))?$|^\d+\/\d+$/.test(q.raw_text||'')?q.raw_text:quantityValue(q),unit=({degC:'°C',angstrom:'Å',um:'µm',count:'count','angstrom^-1':'Å⁻¹','degC/min':'°C/min',ratio_parts:'','cm^-1':'cm⁻¹',monolayer:'ML',fold:'fold',uL:'µL',uW:'µW','ug/L':'µg/L',degree_2theta:'° 2θ','Mohm cm':'MΩ cm'})[q.unit]??q.unit??'';return v===null?(q.raw_text||'Not reported'):`${q.approximate?'≈ ':''}${v}${unit?' '+unit:''}`;}
export function buildPati2009Scene(o,r){
 if(r?.lineage?.source_group!=='pati2009')return null;const c=DATA.configs[r.record_id+'--'+o?.id];if(!c||c.record_id!==r.record_id)return null;
 const rows=Object.entries(o.parameters||{}).map(([k,q])=>({label:DATA.parameter_labels[k]||k.replaceAll('_',' '),value:quantity(q),pointer:c.operation_pointer+'/parameters/'+k,quantity:q,kind:'operation_parameter'}));
 for(const p of c.option_pointers){const option=r.condition_options?.[Number(p.split('/')[2])];if(!option)throw Error('Missing schedule '+p);const quantities=Object.entries(option.parameters).map(([k,q])=>({label:DATA.parameter_labels[k]||k.replaceAll('_',' '),value:quantity(q),pointer:p+'/parameters/'+k,quantity:q}));rows.push({label:option.label,value:quantities.map(x=>x.label+': '+x.value).join('; '),pointer:p,quantities,kind:'alternative_schedule_group'});}
 rows.push(...c.notes.map(n=>({...n,kind:'source_scope_note'})));
 const caption='Source-specific explanatory diagram. Vessel and optical geometry, particle symbols and colors are schematic; measured images and structure data remain separate.';
 const art=draw(c),artSvg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 20 405 460" role="img" aria-label="${esc(c.title)}"><title>${esc(c.title)}</title><desc>${esc(caption)}</desc>${art}</svg>`;
 let y=130,panel='';for(const row of rows){const ll=wrap(row.label,61),vv=wrap(row.value,55);panel+=ll.map((s,i)=>text(430,y+i*16,s,12,'start',C.muted,600)).join('');y+=ll.length*16+6;panel+=vv.map((s,i)=>text(430,y+i*19,s,14,'start')).join('');y+=vv.length*19+20;}
 const divider=Math.max(592,y+4),note=wrap(c.prose,113),height=divider+78+note.length*19;
 const titleLines=wrap(c.title,75);const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 930 ${height}" role="img" aria-label="${esc(c.title)}"><title>${esc(c.title)}</title><desc>${esc(caption)}</desc><rect width="930" height="${height}" rx="16" fill="#fff"/>${titleLines.map((s,i)=>text(28,36+i*25,s,22,'start',C.ink,600)).join('')}${text(28,84,'SYNTHESIS PROTOCOL / EXPERIMENTAL CONTEXT',11,'start',C.muted)}<g transform="translate(0,104)">${art}</g>${rect(408,96,497,divider-110,'#f2f7fa',12,'#dce8ef')}${panel}${path(`M27 ${divider}H903`,'none','#d9e5ec',1)}${note.map((s,i)=>text(28,divider+28+i*19,s,14,'start')).join('')}${text(28,height-18,'Geometry is explanatory; no source atomic coordinates, spectrum or micrograph is synthesized.',11,'start',C.muted)}</svg>`;
 return {kind:r.record_id+'--'+o.id,title:c.title,description:c.prose,caption,rows,svg,artSvg};
}
export function createPati2009Art(o,r){const s=buildPati2009Scene(o,r);if(!s)return null;const h=document.createElement('div');h.className='protocol-art protocol-art-pati2009';h.dataset.scene=s.kind;h.style.height='auto';h.innerHTML=s.artSvg;h.querySelector('svg').style.cssText='display:block;width:100%;height:auto;max-height:none';return h;}
export function createPati2009ConditionGrid(o,r){const s=buildPati2009Scene(o,r);if(!s)return null;const dl=document.createElement('dl');dl.className='protocol-condition-grid';for(const row of s.rows){const d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=row.label;dd.textContent=row.value;d.append(dt,dd);dl.append(d);}return dl;}
export function renderPati2009Markup(s){return `<style>.pati-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:20px;align-items:start}.pati-art svg{display:block;width:100%;height:auto}.pati-conditions{background:#f2f7fa;border:1px solid #dce8ef;border-radius:12px;padding:20px;margin:0}.pati-conditions dt{margin-top:14px;font-size:12px;color:#60788a;line-height:1.5}.pati-conditions dt:first-child{margin-top:0}.pati-conditions dd{margin:4px 0 0;font-size:15px;line-height:1.55;overflow-wrap:anywhere;color:#173a50}.pati-note{font-size:15px;line-height:1.65}.pati-caption{font-size:12px;line-height:1.6;color:#60788a}</style><div class="pati-grid"><div class="pati-art">${s.artSvg}</div><dl class="pati-conditions">${s.rows.map(x=>`<dt>${esc(x.label)}</dt><dd>${esc(x.value)}</dd>`).join('')}</dl></div><p class="pati-note">${esc(s.description)}</p><p class="pati-caption">${esc(s.caption)}</p>`;}
export const pati2009SceneSelection={source_group:'pati2009',records:Object.fromEntries([...new Set(Object.values(DATA.configs).map(c=>c.record_id))].map(id=>[id,Object.entries(DATA.configs).filter(([k,c])=>c.record_id===id).map(([,c])=>c.operation_id)]))};
